import { z } from 'zod';
import dbsManifestJson from '../data/generated/manifest.json';
import labelsJson from '../data/generated/ctx-labels.json';
import manifestJson from '../data/generated/ctx-manifest.json';
import { CtxManifestSchema } from '../data/schema';

/**
 * Cortex section data, generated by pipeline/cortex_build.py: the Destrieux 2009 gyri and sulci on the
 * Lead-DBS template surface (MNI 2009b), with facts taken from Destrieux et al. 2010 Table 1 and
 * measurements made on that surface.
 */
export const CTX_MANIFEST = CtxManifestSchema.parse(manifestJson);
export const CTX = new Map(CTX_MANIFEST.structures.map((s) => [s.id, s]));
export const MEDIAL_WALL = 'ctx_medial_wall';

const V3 = z.tuple([z.number(), z.number(), z.number()]);
const Anchor = z.object({ pial: V3, inflated: V3, nPial: V3, nInflated: V3 });
const LobeId = z.enum(['frontal', 'parietal', 'temporal', 'occipital', 'cingulate', 'insula']);
export type LobeId = z.infer<typeof LobeId>;
const Definition = z.object({ text: z.string().min(1), url: z.string().url().nullable(), source: z.string() });
export const LabelSchema = z.object({
  id: z.string().regex(/^ctx_[a-z0-9_]+$/),
  short: z.string(),
  index: z.number().int(),
  name: z.string(),
  kind: z.enum(['gyrus', 'sulcus', 'gyrus and sulcus', 'pole']),
  views: z.array(z.enum(['S', 'A', 'L', 'P', 'M', 'I'])),
  paperAreaCm2: z.object({ L: z.number(), R: z.number() }),
  areaCm2: z.object({ L: z.number(), R: z.number() }),
  lobe: LobeId,
  lobeShare: z.number(),
  /** the colour lobe comes from the measured shares, or from the Destrieux name (cingulate gyrus, circular sulcus of the insula) */
  lobeBy: z.enum(['measure', 'name']),
  lobes: z.array(z.object({ lobe: LobeId, share: z.number() })).min(1),
  atlasColour: z.string().regex(/^#[0-9a-f]{6}$/),
  anchor: z.object({ L: Anchor, R: Anchor }),
  borders: z.array(z.object({ id: z.string(), share: z.number() })),
  dk: z.array(z.object({ region: z.string(), labelInRegion: z.number(), regionInLabel: z.number() })),
  parcels: z.array(z.object({ id: z.string(), labelInParcel: z.number(), parcelInLabel: z.number() })),
  insula: z.boolean(),
  definition: Definition.extend({ scope: z.string().nullable() }).nullable(),
});
export type CtxLabel = z.infer<typeof LabelSchema>;
const FileSchema = z.object({
  labels: z.array(LabelSchema),
  lobes: z.array(z.object({ id: LobeId, name: z.string(), token: z.string(), definition: Definition.nullable(), labels: z.array(z.string()) })),
  method: z.object({
    faces: z.number(), inflateIterations: z.number(), inflateStep: z.number(), midlineGapMm: z.number(),
    operMarginMm: z.number(), operLateralMm: z.number(), hmatMaxDistMm: z.number(),
  }),
  report: z.record(z.unknown()),
});
const FILE = FileSchema.parse(labelsJson);
export const LABELS = FILE.labels;
export const LABEL = new Map(LABELS.map((l) => [l.id, l]));
export const LOBES = FILE.lobes;
export const LOBE = new Map(LOBES.map((l) => [l.id, l]));
export const METHOD = FILE.method;

/** Name for labels and lists: the Destrieux long name without parenthetical synonyms, up to its first comma. */
export function shortName(id: string): string {
  if (id === MEDIAL_WALL) return 'Medial wall';
  const l = LABEL.get(id);
  if (!l) return CTX.get(id)?.name ?? id;
  return l.name.replace(/\s*\([^)]*\)/g, '').split(',')[0].replace(/\s+/g, ' ').trim();
}

/** Desikan-Killiany region names as shown (FreeSurfer's names are run together). */
export const DK_NAMES: Record<string, string> = {
  bankssts: 'banks of the superior temporal sulcus', caudalanteriorcingulate: 'caudal anterior cingulate', caudalmiddlefrontal: 'caudal middle frontal',
  cuneus: 'cuneus', entorhinal: 'entorhinal', frontalpole: 'frontal pole', fusiform: 'fusiform', inferiorparietal: 'inferior parietal',
  inferiortemporal: 'inferior temporal', insula: 'insula', isthmuscingulate: 'isthmus of the cingulate', lateraloccipital: 'lateral occipital',
  lateralorbitofrontal: 'lateral orbitofrontal', lingual: 'lingual', medialorbitofrontal: 'medial orbitofrontal', middletemporal: 'middle temporal',
  paracentral: 'paracentral', parahippocampal: 'parahippocampal', parsopercularis: 'pars opercularis', parsorbitalis: 'pars orbitalis',
  parstriangularis: 'pars triangularis', pericalcarine: 'pericalcarine', postcentral: 'postcentral', posteriorcingulate: 'posterior cingulate',
  precentral: 'precentral', precuneus: 'precuneus', rostralanteriorcingulate: 'rostral anterior cingulate', rostralmiddlefrontal: 'rostral middle frontal',
  superiorfrontal: 'superior frontal', superiorparietal: 'superior parietal', superiortemporal: 'superior temporal', supramarginal: 'supramarginal',
  temporalpole: 'temporal pole', transversetemporal: 'transverse temporal',
};

/** Names of the DBS section's cortical parcels (HMAT motor areas, Desikan-Killiany ACC / vmPFC proxy). */
const DBS_STRUCTURES = (dbsManifestJson as { structures: { id: string; name: string; derivation: string }[] }).structures;
export const DBS_PARCEL = new Map(DBS_STRUCTURES.filter((s) => ['m1', 's1', 'sma', 'presma', 'pmd', 'pmv', 'acc', 'vmpfc'].includes(s.id)).map((s) => [s.id, s]));

/** Cross-checks between the generated files. Returns a list of problems (empty = consistent). */
export function crossCheckCtx(): string[] {
  const errs: string[] = [];
  for (const l of LABELS) {
    if (!CTX.has(l.id)) errs.push(`${l.id}: no manifest structure`);
    for (const b of l.borders) if (!CTX.has(b.id)) errs.push(`${l.id}: border ${b.id} unknown`);
    for (const p of l.parcels) if (!DBS_PARCEL.has(p.id)) errs.push(`${l.id}: DBS parcel ${p.id} unknown`);
    for (const r of l.dk) if (!DK_NAMES[r.region]) errs.push(`${l.id}: Desikan-Killiany region ${r.region} unnamed`);
    if (!l.lobes.some((x) => x.lobe === l.lobe)) errs.push(`${l.id}: main lobe not among its lobes`);
  }
  for (const lb of LOBES) for (const id of lb.labels) if (!LABEL.has(id)) errs.push(`lobe ${lb.id}: unknown label ${id}`);
  for (const s of CTX_MANIFEST.structures) if (s.id !== MEDIAL_WALL && !LABEL.has(s.id)) errs.push(`${s.id}: no label facts`);
  return errs;
}
